parameters.jsCode:
// Bericht erstellen (SHOPIFY 2, Migration 82/85, Stefan 22.10.2026): Verkaufszahlen der gewählten Produkte über ShopifyQL (read_reports, nur Summen, nie Bestellungen
// oder Kundendaten), daraus PDF (im Corporate Design, über den internen Render-Dienst ally-render) und/oder CSV (Semikolon, UTF-8 mit BOM). Läuft das Token bald ab,
// wird es vorher erneuert (Angaben nur aus shopify_lauf_start). Keine Ausführungsdaten (Einstellung des Ablaufs). Ausgabe: ein Item mit den Dateien und den Plänen
// für Versand und Ablage; Fehler als Text (der Lauf endet dann mit Fehler).
// Migration 98 (Stefan 22.10.2026, 21:34/21:35/21:38): Zahlen nach deutschem Sprachgebrauch (§ 277 Abs. 1 HGB: Umsatzerlöse nach Erlösschmälerungen, ohne Umsatzsteuer):
// Umsatz netto (= net_sales, ohne Umsatzsteuer) und Umsatz brutto (= net_sales + taxes, mit Umsatzsteuer) immer; wählbar Überleitung (Verkaufswert, Rabatte, Erstattungen
// und Rückgaben, Umsatz netto, Umsatzsteuer, Umsatz brutto), Mengen (Bestellungen, verkaufte Stück, zurückgegebene Stück), Varianten, Vergleich (Zeitraum davor oder
// Vorjahr; ohne Verkäufe im Vergleichszeitraum „keine Verkäufe im …“ statt „neu gegenüber 0,00 €“), Entwicklung. Kopf mit Eckdaten, Datenhinweise am Ende.
// Shopify liefert Rabatte und Erstattungen als Minusbeträge (geprüft 23.10.2026); hier immer als Abzug geführt.
// Migration 100 (Prüfung 23.10.2026): Vergleich mit Betrag und Prozent der Veränderung (auch in der Überleitung); ohne Verkäufe im Vergleichszeitraum ein klarer Satz statt
// einer Spalte voller 0,00 €; Überleitung ohne doppelte Verneinung (Rabatte −40,00 €); CSV-Spalten in der Reihenfolge der Überleitung; Summenzeile „Je Variante“.
const API = '2026-10';
const RENDER = 'http://ally-render:3000';
const L0 = ($input.first().json || {}).l || {};
const istBuf = x => typeof Buffer !== 'undefined' && Buffer.isBuffer(x);
const lies = b => { if (b && typeof b === 'object' && !istBuf(b)) return b; try { return JSON.parse(istBuf(b) ? b.toString('utf8') : String(b || '')); } catch (e) { return null; } };
const rein = (v, n) => Array.from(String(v ?? '').replace(/[\uD800-\uDFFF]/gu, '').replace(/[\u0000-\u0008\u000b\u000c\u000e-\u001f\u007f]/g, ' ')).slice(0, n || 500).join('');
const lauf_id = /^[0-9]{1,18}$/.test(String(L0.lauf_id || '')) ? String(L0.lauf_id) : '';
const z = L0.zugang || {};
const shop_id = /^[0-9]{1,9}$/.test(String(z.shop_id || '')) ? String(z.shop_id) : '';
const raus = (fehler, extra) => [{ json: Object.assign({ lauf_id, shop_id, ok: false, fehler: rein(fehler, 900), neu: '', summen: null, versand: { an: false }, ablage: { an: false }, dateien: [] }, extra || {}) }];
if (L0.ok !== true) return raus(L0.fehler || 'Der Lauf konnte nicht gestartet werden.');
const DOM = /^[a-z0-9][a-z0-9-]{0,59}\.myshopify\.com$/;
if (!DOM.test(String(z.domain || ''))) return raus('Ungültige Shop-Adresse.');
const EI = L0.einstellungen || {};
const Z = L0.zeitraum || {};
const DAT = /^\d{4}-\d{2}-\d{2}$/;
if (!DAT.test(String(Z.von || '')) || !DAT.test(String(Z.bis || ''))) return raus('Der Zeitraum ist ungültig.');
// Begriffe und Erklärungen aus der Datenbank (shopify_kennzahlen, Migration 98); fester Rückfall nur für die Namen
const KD = Object.fromEntries((Array.isArray(L0.kennzahlen) ? L0.kennzahlen : []).filter(k => k && /^[a-z_]{1,30}$/.test(String(k.k || ''))).map(k => [k.k, k]));
const K = (k, name, art) => ({ k, name: rein((KD[k] || {}).name || name, 80), art: (KD[k] || {}).art || art, info: rein((KD[k] || {}).info || '', 400) });
const KN = { verkaufswert: K('verkaufswert', 'Verkaufswert', 'geld'), rabatte: K('rabatte', 'Rabatte', 'geld'), erstattungen: K('erstattungen', 'Erstattungen und Rückgaben', 'geld'),
  korrektur: { k: 'korrektur', name: 'Sonstige Korrekturen', art: 'geld', info: 'Differenz, die Shopify keiner der Zeilen darüber zuordnet.' },
  netto: K('netto', 'Umsatz netto', 'geld'), ust: K('ust', 'Umsatzsteuer', 'geld'), brutto: K('brutto', 'Umsatz brutto', 'geld'),
  bestellungen: K('bestellungen', 'Bestellungen', 'zahl'), stueck: K('stueck', 'Verkaufte Stück', 'zahl'), zurueck: K('zurueck', 'Zurückgegebene Stück', 'zahl') };
// Auswahl des Berichts: Umsatz netto und brutto immer; Überleitung und Mengen wählbar (ältere Einstellungen: aus der früheren Auswahl „kennzahlen“ abgeleitet)
const altKZ = Array.isArray(EI.kennzahlen) ? EI.kennzahlen.map(String) : [];
const UEBER = EI.ueberleitung === true || (EI.ueberleitung === undefined && altKZ.some(k => ['gross_sales', 'discounts', 'sales_reversals', 'total_sales'].includes(k)));
const MENGEN = EI.mengen === true || (EI.mengen === undefined && altKZ.some(k => ['orders', 'quantity_ordered', 'net_items_sold', 'reversed_quantity'].includes(k)));
const VGL = ['vorzeitraum', 'vorjahr'].includes(EI.vergleich) ? EI.vergleich : EI.vergleich === true ? 'vorzeitraum' : 'aus';
const HAUPT = [KN.netto, KN.brutto];
const MENGE = [KN.bestellungen, KN.stueck, KN.zurueck];
const UEB = [KN.verkaufswert, KN.rabatte, KN.erstattungen, KN.netto, KN.ust, KN.brutto];
// Spalten der Tabellen (je Produkt, Variante, Entwicklung): netto, brutto, bei Mengen zusätzlich verkaufte Stück
const SPALTEN = HAUPT.concat(MENGEN ? [KN.stueck] : []);
const PROD = (Array.isArray(L0.produkte) ? L0.produkte : []).filter(p => p && /^[0-9]{1,18}$/.test(String(p.id)));
if (!PROD.length) return raus('Der Bericht enthält keine Produkte (oder sie gibt es im Shop nicht mehr).');
const formate = (Array.isArray(EI.formate) ? EI.formate : []).filter(f => f === 'pdf' || f === 'csv');
if (L0.art === 'partner' && !formate.length) formate.push('pdf');
if (!formate.length) return raus('Kein Format gewählt (PDF oder CSV).');
const W = /^[A-Z]{3}$/.test(String(L0.waehrung || '')) ? String(L0.waehrung) : '';
let neu = '';
const formular = f => Object.keys(f || {}).map(k => encodeURIComponent(k) + '=' + encodeURIComponent(String(f[k] ?? ''))).join('&');

// ---------- Zahlen und Texte ----------
const zahl = v => { const n = typeof v === 'number' ? v : Number(String(v ?? '').replace(/[^0-9.\-eE]/g, '')); return isFinite(n) ? n : 0; };
const r2 = n => Math.round(n * 100) / 100;
const tausend = t => t.replace(/\B(?=(\d{3})+(?!\d))/g, '.');
const fmt = (k, v) => { const n = zahl(v);
  if (k.art === 'geld') { const a = Math.abs(n).toFixed(2).split('.'); return (n < 0 && Math.abs(n) >= 0.005 ? '−' : '') + tausend(a[0]) + ',' + a[1] + (W ? ' ' + (W === 'EUR' ? '€' : W) : ''); }
  return (n < 0 ? '−' : '') + tausend(String(Math.round(Math.abs(n)))); };
const csvZahl = (k, v) => { const n = zahl(v); return k.art === 'geld' ? (Math.abs(n) < 0.005 ? 0 : n).toFixed(2).replace('.', ',') : String(Math.round(n)); };
// Schlussprüfung (Migration 94): Datum ohne führende Nullen („1.9.2026“), Zeiträume mit Gedankenstrich
const datumDE = d => String(d || '').slice(0, 10).split('-').reverse().map(x => String(Number(x))).join('.');
const zrDE = (von, bis) => von === bis ? datumDE(von) : datumDE(von) + ' – ' + datumDE(bis);
const plusTage = (d, n) => { const t = new Date(d + 'T12:00:00Z'); t.setUTCDate(t.getUTCDate() + n); return t.toISOString().slice(0, 10); };
const tageZwischen = (von, bis) => Math.round((Date.parse(bis + 'T12:00:00Z') - Date.parse(von + 'T12:00:00Z')) / 86400000) + 1;
const tageText = n => n === 1 ? '1 Tag' : n + ' Tage';
const monatsEnde = (j, m) => new Date(Date.UTC(j, m, 0, 12)).getUTCDate();  // m = 1..12
// Datum um n Monate verschieben; Tag höchstens bis Monatsende (31.3. minus 1 Monat = 28./29.2.)
const minusMonate = (d, n) => { let j = Number(d.slice(0, 4)), m = Number(d.slice(5, 7)) - n; while (m < 1) { m += 12; j--; }
  return j + '-' + String(m).padStart(2, '0') + '-' + String(Math.min(Number(d.slice(8, 10)), monatsEnde(j, m))).padStart(2, '0'); };

// ---------- Shopify ----------
let token = String(z.token || '');
const abfragen = [];
const ql = async (art, q) => {
  const a = await this.helpers.httpRequest({ method: 'POST', url: 'https://' + z.domain + '/admin/api/' + API + '/graphql.json',
    body: { query: 'query($q: String!) { shopifyqlQuery(query: $q) { tableData { columns { name dataType } rows } parseErrors } }', variables: { q } },
    headers: { 'X-Shopify-Access-Token': token, 'Content-Type': 'application/json' }, json: true, timeout: 90000, returnFullResponse: true, ignoreHttpStatusErrors: true });
  if (a.statusCode === 401 || a.statusCode === 403) throw new Error('Shopify lehnt den Zugang ab (' + a.statusCode + '). Die App muss in Shopify neu geöffnet bzw. installiert werden.');
  if (a.statusCode !== 200) throw new Error('Shopify antwortet mit Fehler ' + a.statusCode + '.');
  const d = lies(a.body) || {};
  const r = (d.data || {}).shopifyqlQuery;
  let fehler = '';
  if (d.errors && d.errors.length) fehler = rein(d.errors.map(e => e && e.message ? e.message : JSON.stringify(e)).join(' '), 300);
  else if (!r) fehler = 'keine Antwort';
  else if (Array.isArray(r.parseErrors) && r.parseErrors.length) fehler = rein(r.parseErrors.map(e => typeof e === 'string' ? e : (e && (e.message || e.code)) || JSON.stringify(e)).join(' '), 300);
  const rows0 = r && r.tableData ? (typeof r.tableData.rows === 'string' ? lies(r.tableData.rows) : r.tableData.rows) : null;
  const rows = Array.isArray(rows0) ? rows0 : [];
  abfragen.push({ art, zeilen: rows.length, fehler: fehler || undefined, q: rein(q, 400) });
  return { ok: !fehler, fehler, rows, spalten: r && r.tableData && Array.isArray(r.tableData.columns) ? r.tableData.columns.map(c => String(c.name || '')) : [] };
};
const zeit = (von, bis) => 'SINCE ' + von + ' UNTIL ' + bis;
// Immer dieselben Shopify-Werte abfragen (eine Abfrage je Teil); daraus alle Zahlen des Berichts
const SHOW = 'SHOW gross_sales, discounts, sales_reversals, net_sales, taxes, orders, net_items_sold, reversed_quantity';
const pid = v => String(v ?? '').split('/').pop();
const werte = row => { const x = row || {};
  const vk = r2(zahl(x.gross_sales)), rab = -r2(Math.abs(zahl(x.discounts))), ers = -r2(Math.abs(zahl(x.sales_reversals))), net = r2(zahl(x.net_sales)), ust = r2(zahl(x.taxes));
  return { verkaufswert: vk, rabatte: rab, erstattungen: ers, korrektur: r2(net - (vk + rab + ers)), netto: net, ust, brutto: r2(net + ust),
    bestellungen: Math.round(zahl(x.orders)), stueck: Math.round(zahl(x.net_items_sold)), zurueck: Math.abs(Math.round(zahl(x.reversed_quantity))) }; };
const FELDER = ['verkaufswert', 'rabatte', 'erstattungen', 'korrektur', 'netto', 'ust', 'brutto', 'bestellungen', 'stueck', 'zurueck'];
const summe = liste => { const o = Object.fromEntries(FELDER.map(k => [k, liste.reduce((a, x) => a + zahl((x || {})[k]), 0)])); for (const k of FELDER) o[k] = r2(o[k]); return o; };
const ids = PROD.map(p => p.id);
const filterIn = 'WHERE product_id IN (' + ids.join(', ') + ')';

try {
  // Zugang erneuern (wie SHOPIFY 3)
  if (z.erneuern === true) {
    if (String(z.url || '') !== 'https://' + z.domain + '/admin/oauth/access_token') return raus('Ungültige Adresse zum Erneuern.');
    const a = await this.helpers.httpRequest({ method: 'POST', url: z.url, body: formular(z.form), headers: { 'Content-Type': 'application/x-www-form-urlencoded', Accept: 'application/json' },
      json: false, timeout: 30000, returnFullResponse: true, ignoreHttpStatusErrors: true });
    const d = lies(a.body);
    if (a.statusCode !== 200 || !d || !d.access_token) return raus('Der Zugang konnte nicht erneuert werden (' + a.statusCode + '). Die App muss in Shopify neu geöffnet bzw. installiert werden.');
    const keep = {}; for (const k of ['access_token', 'scope', 'expires_in', 'refresh_token', 'refresh_token_expires_in']) if (d[k] !== undefined) keep[k] = d[k];
    neu = JSON.stringify(keep); token = d.access_token;
  }
  if (!token) return raus('Kein Zugang zum Shop.', { neu });

  // 1. Je Produkt (WHERE … IN; falls ShopifyQL das ablehnt: je Produkt einzeln)
  const jeProdukt = {};
  const r1 = await ql('produkte', 'FROM sales ' + SHOW + ' ' + filterIn + ' GROUP BY product_id, product_title ' + zeit(Z.von, Z.bis) + ' LIMIT 1000');
  const einzeln = !r1.ok;
  if (r1.ok) for (const row of r1.rows) jeProdukt[pid(row.product_id)] = werte(row);
  else {
    for (const p of PROD) {
      const r = await ql('produkt', 'FROM sales ' + SHOW + ' WHERE product_id = ' + p.id + ' ' + zeit(Z.von, Z.bis));
      if (!r.ok) throw new Error('Die Verkaufszahlen konnten nicht abgefragt werden: ' + r.fehler);
      jeProdukt[p.id] = summe(r.rows.map(werte));
    }
  }
  const leer = werte({});
  const zeilenP = PROD.map(p => ({ id: p.id, titel: rein(p.titel, 300), werte: jeProdukt[p.id] || leer }));
  // 2. Gesamt (bei IN als eigene Abfrage, damit Bestellungen mit mehreren Produkten nur einmal zählen)
  let gesamt = summe(zeilenP.map(x => x.werte)), gesamtHinweis = '';
  if (!einzeln && PROD.length > 1) {
    const r2a = await ql('gesamt', 'FROM sales ' + SHOW + ' ' + filterIn + ' ' + zeit(Z.von, Z.bis));
    if (r2a.ok && r2a.rows.length) gesamt = werte(r2a.rows[0]);
  } else if (einzeln && PROD.length > 1 && MENGEN) gesamtHinweis = 'Bestellungen mit mehreren der Produkte zählen in der Summe je Produkt.';
  const wo = einzeln && PROD.length === 1 ? 'WHERE product_id = ' + PROD[0].id : filterIn;
  // 3. Varianten
  let varianten = null;
  if (EI.varianten === true) {
    const r3 = await ql('varianten', 'FROM sales ' + SHOW + ' ' + wo + ' GROUP BY product_id, product_title, product_variant_id, product_variant_title ' + zeit(Z.von, Z.bis) + ' LIMIT 1000');
    if (r3.ok) varianten = r3.rows.map(row => ({ produkt_id: pid(row.product_id), produkt: rein(row.product_title || (PROD.find(p => p.id === pid(row.product_id)) || {}).titel, 300),
      variante_id: pid(row.product_variant_id), variante: rein(row.product_variant_title && row.product_variant_title !== 'Default Title' ? row.product_variant_title : 'Standard', 200), werte: werte(row) }))
      .sort((a, b) => (a.produkt + a.variante).localeCompare(b.produkt + b.variante, 'de'));
    else varianten = { fehler: r3.fehler };
  }
  // 4. Entwicklung im Zeitraum
  let verlauf = null;
  if (['day', 'week', 'month'].includes(EI.verlauf)) {
    const r4 = await ql('verlauf', 'FROM sales ' + SHOW + ' ' + wo + ' TIMESERIES ' + EI.verlauf + ' ' + zeit(Z.von, Z.bis) + ' ORDER BY ' + EI.verlauf + ' ASC LIMIT 1000');
    if (r4.ok) verlauf = r4.rows.map(row => ({ datum: String(row[EI.verlauf] ?? '').slice(0, 10), werte: werte(row) })).filter(x => DAT.test(x.datum));
    else verlauf = { fehler: r4.fehler };
  }
  // 5. Vergleich: Vorjahr = dieselben Tage ein Jahr früher. Zeitraum davor: ganze Monate (Vormonat, Quartal, Jahr …) mit den Monaten davor; ein angefangener Monat
  //    (1. bis Stichtag, z. B. laufender Monat) mit denselben Tagen des Vormonats; sonst gleich viele Tage direkt davor.
  let vz = null;
  if (VGL === 'vorjahr') vz = { von: minusMonate(Z.von, 12), bis: minusMonate(Z.bis, 12), name: 'Vorjahr', im: 'im Vorjahreszeitraum' };
  else if (VGL === 'vorzeitraum') {
    const ende = plusTage(Z.bis, 1);
    const mon = Z.von.slice(8) === '01' && ende.slice(8) === '01' ? (Number(ende.slice(0, 4)) - Number(Z.von.slice(0, 4))) * 12 + Number(ende.slice(5, 7)) - Number(Z.von.slice(5, 7)) : 0;
    if (mon > 0) vz = { von: minusMonate(Z.von, mon), bis: plusTage(Z.von, -1), name: mon === 1 ? 'Vormonat' : mon === 3 ? 'Vorquartal' : mon === 12 ? 'Vorjahr' : mon + ' Monate davor' };
    else if (Z.von.slice(8) === '01' && Z.von.slice(0, 7) === Z.bis.slice(0, 7)) vz = { von: minusMonate(Z.von, 1), bis: minusMonate(Z.bis, 1), name: 'gleiche Tage im Vormonat' };
    else { const tage = Math.max(1, Math.round((Date.parse(Z.bis + 'T12:00:00Z') - Date.parse(Z.von + 'T12:00:00Z')) / 86400000) + 1);
      vz = { von: plusTage(Z.von, -tage), bis: plusTage(Z.von, -1), name: tage === 1 ? 'Vortag' : 'die ' + tage + ' Tage davor' }; }
    vz.im = 'im Vergleichszeitraum';
  }
  let vergleich = null;
  if (vz) {
    const r5 = await ql('vergleich', 'FROM sales ' + SHOW + ' ' + wo + ' ' + zeit(vz.von, vz.bis));
    if (r5.ok) vergleich = r5.rows.length ? werte(r5.rows[0]) : werte({});
    else vergleich = { fehler: r5.fehler };
  }
  const VG = vergleich && !vergleich.fehler ? vergleich : null;
  if (einzeln && !Object.keys(jeProdukt).length) throw new Error('Die Verkaufszahlen konnten nicht abgefragt werden.');
  const stand = new Date().toLocaleString('de-DE', { timeZone: 'Europe/Berlin', day: 'numeric', month: 'numeric', year: 'numeric', hour: '2-digit', minute: '2-digit' });
  // Veränderung gegenüber dem Vergleichszeitraum: ohne Werte dort kein Prozentwert, sondern ein Satz
  // Migration 100: Veränderung als Betrag und Prozent, z. B. „+99,00 € (+44,0 %)“ bzw. „+4 (+50,0 %)“; ohne Wert im Vergleichszeitraum nur der Betrag
  const VGLEER = !!VG && FELDER.every(f => Math.abs(zahl(VG[f])) < 0.005);
  const diffTxt = (k, d) => (d > 0.004 ? '+' : d < -0.004 ? '−' : '±') + fmt(k, Math.abs(d));
  // Prüfung 23.10.2026: Bei Abzügen wäre „+4,60 €“ missverständlich (weniger Rabatt). Deshalb der Betrag mit „mehr/weniger Rabatt“ bzw. „mehr/weniger erstattet“.
  const ABZUG = { rabatte: 'Rabatt', erstattungen: 'erstattet' };
  const diff = (k, b0, a0) => { const a = zahl(a0), b = zahl(b0), d = r2(b - a);
    if (ABZUG[k.k]) { const dd = r2(Math.abs(b) - Math.abs(a)); return Math.abs(dd) < 0.005 ? 'unverändert' : fmt(k, Math.abs(dd)) + (dd > 0 ? ' mehr ' : ' weniger ') + ABZUG[k.k]; }
    if (Math.abs(a) < 0.005) return Math.abs(b) < 0.005 ? 'unverändert' : diffTxt(k, d);
    if (a < 0) return diffTxt(k, d);  // Abzüge (Rabatte, Erstattungen): nur der Betrag, ein Prozentwert auf einen Minusbetrag wäre missverständlich
    const p = (b - a) / Math.abs(a) * 100;
    return diffTxt(k, d) + ' (' + (p > 0.05 ? '+' : p < -0.05 ? '−' : '±') + Math.abs(p).toFixed(1).replace('.', ',') + ' %)'; };
  const veraenderung = k => { if (!VG) return null; const a = zahl(VG[k.k]), b = zahl(gesamt[k.k]);
    if (Math.abs(a) < 0.005) return Math.abs(b) < 0.005 ? { text: 'unverändert', r: 'gleich', satz: 'auch ' + vz.im + ' keine Verkäufe' }
      : { text: '', r: 'gleich', satz: k.art === 'zahl' && k.k === 'zurueck' ? 'keine ' + vz.im : 'keine Verkäufe ' + vz.im };
    const p = (b - a) / Math.abs(a) * 100;
    return { text: diff(k, b, a), r: p > 0.05 ? 'hoch' : p < -0.05 ? 'runter' : 'gleich', satz: 'vorher ' + fmt(k, a) }; };
  const leerSatz = vz ? 'Keine Verkäufe im Vergleichszeitraum (' + zrDE(vz.von, vz.bis) + ', ' + vz.name + ').' : '';

  // ---------- Dateiname ----------
  const sauber = t => rein(t, 120).replace(/[\\/:*?"<>|\u0000-\u001f]/g, '-').replace(/\s+/g, ' ').trim();
  const basis = sauber('Verkaufsbericht ' + (L0.name || '') + ' ' + Z.von + ' bis ' + Z.bis);
  const erstellt = String(L0.erstellt || stand);
  const shopText = [rein(L0.shop_name || L0.shop, 200), String(L0.domain || '')].filter(Boolean).join(' · ');
  const unternehmen = rein(((L0.cd || {}).unternehmen) || '', 200);
  const produktName = rein(L0.produkt_name || 'Ally', 60);
  const zrText = zrDE(Z.von, Z.bis);
  const vzText = vz ? zrDE(vz.von, vz.bis) + ' (' + tageText(tageZwischen(vz.von, vz.bis)) + ', ' + vz.name + ')' : '';
  const wText = W ? W + (W === 'EUR' ? ' (Euro)' : '') : '–';
  const dateien = [];
  const binary = {};

  // ---------- CSV ----------
  if (formate.includes('csv') || L0.art === 'partner') {
    // Reine Zahlen (z. B. -12,50 bei Rabatten) bleiben Zahlen; alles andere mit führendem = + - @ wird gegen Formeln geschützt
    const q = v => { const t = String(v ?? ''); if (/^-?[0-9]+(,[0-9]+)?$/.test(t)) return t; return /[;"\n\r]/.test(t) || /^[=+\-@]/.test(t) ? '"' + (/^[=+\-@]/.test(t) ? "'" : '') + t.replace(/"/g, '""') + '"' : t; };
