  return [{ json: { lauf_id, shop_id, ok: true, fehler: '', neu, art: String(L0.art || ''),
    summen: { waehrung: W, von: Z.von, bis: Z.bis, gesamt, produkte: zeilenP.map(p => ({ id: p.id, werte: p.werte })), vergleich: VG || undefined,
      vergleich_zeitraum: vz ? { von: vz.von, bis: vz.bis, name: vz.name } : undefined, abfragen },
    versand: { an: V.an === true, bereit: V.bereit === true, empfaenger: (Array.isArray(V.empfaenger) ? V.empfaenger : []).map(String).filter(x => /^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,190}$/.test(x)).slice(0, 20),
      von: V.absender ? (V.absender_name && V.absender_name !== V.absender ? '"' + rein(V.absender_name, 80).replace(/"/g, '') + '" <' + V.absender + '>' : String(V.absender)) : '', absender: String(V.absender || ''),
      betreff, text, html: mailHtml },
    ablage: { an: A.an === true && !!ordner, ordner, stempel },
    dateien }, binary }];
} catch (e) {
  return raus(rein(e.message || e, 600) + (abfragen.length ? ' [' + abfragen.map(a => a.art + ':' + a.zeilen + (a.fehler ? ' ' + a.fehler : '')).join('; ').slice(0, 250) + ']' : ''), { neu });
}

// Mail-Aufträge (SHOPIFY 2, Migration 86): je Adresse eine eigene Mail mit den Dateien im Anhang, über das Postfach des Berichts (Weg 12 = Workflow des
// Postfachs) oder – nur ohne gewähltes Postfach – über den Absender für Systemnachrichten (Weg 0). P5 (Aufräumen nach P4): Weg 1–10 (Platz-Knoten) entfernt. Nur fertige Verkaufsberichte aus Zeitplan oder „Jetzt senden“
// (nie Partner-Abrufe, nie Testdaten, nie Entwürfe); Platz und Bereitschaft kommen nur aus der Datenbank (shopify_lauf_start). Sonst ein Item „keine“ (Weg 11).
const it = $('Bericht erstellen').first();
const j = it.json || {};
const V = ((($('Lauf starten').first().json || {}).l || {}).versand) || {};
const M = j.versand || {};
const an = (Array.isArray(M.empfaenger) ? M.empfaenger : []).filter(x => /^[^\s@<>"',;]{1,64}@[^\s@<>"',;]{1,190}$/.test(String(x))).slice(0, 20);
// Migration 173 (Schritt P, P3): Postfach mit eigenem Workflow (weg = eigen) sendet über „MAIL Postfach Nr. n“ (Weg 12, Unterablauf „Aufruf“, Aktion senden)
const eigen = V.weg === 'eigen' && Number.isInteger(V.platz) && V.platz >= 1 && /^[A-Za-z0-9]{8,40}$/.test(String(V.workflow_id || ''));
const weg = eigen ? 12 : V.platz === 0 ? 0 : -1;
if (j.ok !== true || V.an !== true || V.test === true || V.bereit !== true || weg < 0 || !M.von || !an.length || !['plan', 'jetzt'].includes(String(j.art || ''))) return [{ json: { keine: true, weg: 11 } }];
const anh = (Array.isArray(j.dateien) ? j.dateien : []).map(d => d.feld).filter(f => it.binary && it.binary[f]);
if (!anh.length) return [{ json: { keine: true, weg: 11 } }];
// Migration 92 (Stefan 22.10.2026, 18:13): fertige Mail aus der Datenbank (eigener Text oder Standard, Platzhalter eingesetzt, Signatur des Absenders), sonst wie bisher
const FM = V.mail && typeof V.mail === 'object' && String(V.mail.betreff || '') && String(V.mail.html || '') ? V.mail : null;
const betreff = String(FM ? FM.betreff : M.betreff || '').replace(/[\r\n]+/g, ' ').slice(0, 200), text = String(FM ? FM.text || '' : M.text || ''), html = String(FM ? FM.html : M.html || '');
return an.map(a => ({ json: Object.assign({ weg, an: a, von: String(M.von), betreff, text, html, anhaenge: anh.join(',') },
  eigen ? { aktion: 'senden', nr: V.platz, workflow_id: String(V.workflow_id) } : {}), binary: it.binary }));

// Ablage-Aufträge (SHOPIFY 2, Migration 86): Ergebnis des Versands festhalten (eigener Versand des Postfachs bzw. Absender für Systemnachrichten; bei Testdaten nur
// „würde senden“) und je Datei einen Auftrag „ablegen“ für SPEICHER 1 (Bereich ally, Ordner des Berichts, nie überschreiben, Dateiname mit Zeitstempel). Nur wenn der Bericht
// erstellt ist und die Ablage eingeschaltet ist (nie bei Testdaten oder Partner-Abrufen). Sonst ein Item „keine“.
const it = $('Bericht erstellen').first();
const j = it.json || {}, M = j.versand || {}, A = j.ablage || {};
const V = ((($('Lauf starten').first().json || {}).l || {}).versand) || {};
const MAILS = ['Mail (Systemnachrichten)', 'Mail über Postfach-Workflow'];  // P5 (Aufräumen nach P4): ohne die Platz-Knoten
const ueber = V.platz === 0 ? 'über den Absender für Systemnachrichten (' + (V.absender || '') + ')' : 'über das Postfach ' + (V.absender || '');
const empf = (Array.isArray(V.empfaenger) ? V.empfaenger : []).map(String);
let versand = '', versand_ok = null;
if (j.ok === true && V.test === true) {
  versand = V.bereit === true ? 'Testmodus: würde an ' + empf.length + (empf.length === 1 ? ' Adresse' : ' Adressen') + ' (' + empf.join(', ') + ') ' + ueber + ' senden. Nichts versendet.'
    : 'Testmodus: würde nicht senden – ' + (V.gewaehlt ? 'für das Postfach ' + V.gewaehlt + ' ist der Versand nicht eingerichtet.' : 'kein Absender-Postfach gewählt und kein Absender für Systemnachrichten eingerichtet.');
} else if (j.ok === true && V.an === true) {
  if (V.bereit !== true) { versand = 'Nicht versendet: ' + (V.gewaehlt ? 'Für das Postfach ' + V.gewaehlt + ' ist der Versand nicht eingerichtet (Einstellungen › Meine Postfächer bzw. Gemeinsame Postfächer, Abschnitt „Zugang und Versand“).'
      : 'Kein Absender-Postfach gewählt und kein Absender für Systemnachrichten eingerichtet.'); versand_ok = false; }
  else {
    const R = [].concat(...MAILS.map(n => $(n).isExecuted ? $(n).all() : []));
    const fehl = R.filter(r => r.json && r.json.error);
    const ok = R.length - fehl.length;
    versand_ok = ok > 0 && fehl.length === 0;
    versand = !R.length ? 'Nicht versendet: keine gültige Mail-Adresse.' : ok === R.length ? 'Versendet an ' + ok + (ok === 1 ? ' Adresse' : ' Adressen') + ' (' + empf.join(', ') + ') ' + ueber + '.'
      : 'Versendet an ' + ok + ' von ' + R.length + ' Adressen ' + ueber + '. Fehler: ' + String((fehl[0] && fehl[0].json.error && (fehl[0].json.error.message || fehl[0].json.error)) || 'unbekannt').slice(0, 200);
    if (!R.length) versand_ok = false;
  }
}
const basis = { versand, versand_ok };
const dateien = (Array.isArray(j.dateien) ? j.dateien : []).filter(d => it.binary && it.binary[d.feld]);
if (j.ok !== true || A.an !== true || !A.ordner || !dateien.length) return [{ json: Object.assign({ keine: true }, basis) }];
const sauber = t => String(t || '').replace(/[\\/:*?"<>|\u0000-\u001f]/g, '-');
return dateien.map(d => { const punkt = d.name.lastIndexOf('.');
  const name = sauber(d.name.slice(0, punkt) + ' (erstellt ' + String(A.stempel || '') + ')' + d.name.slice(punkt));
  return { json: Object.assign({ aktion: 'ablegen', bereich: 'ally', pfad: A.ordner + '/' + name, ueberschreiben: false }, basis), binary: { datei: it.binary[d.feld] } }; });

// Ende vorbereiten (SHOPIFY 2): Ergebnis für shopify_lauf_ende (ok, fehler, summen, versand, ablage). Ohne Inhalte der Dateien und ohne Zugangsdaten.
// Migration 98: dazu die Pfade der abgelegten Dateien (Bereich ally), damit Ally später erkennt, ob sie im Ordner gelöscht wurden.
const j = $('Bericht erstellen').first().json || {};
const A0 = $('Ablage-Aufträge').all().map(x => x.json || {});
const basis = A0[0] || {};
let ablage = '', ablage_ok = null, ablage_pfade = [];
if (j.ok === true && (j.ablage || {}).an === true) {
  const R = $('Ablegen (SPEICHER 1)').isExecuted ? $('Ablegen (SPEICHER 1)').all().map(x => x.json || {}) : [];
  if (!R.length) { ablage = 'Nicht abgelegt.'; ablage_ok = false; }
  else {
    const fehl = R.filter(r => r.ok !== true);
    ablage_ok = fehl.length === 0;
    ablage_pfade = R.filter(r => r.ok === true && typeof r.pfad === 'string' && r.pfad).map(r => String(r.pfad).slice(0, 1000)).slice(0, 10);
    ablage = ablage_ok ? 'Abgelegt in ' + String(R[0].ort || 'Speicherort') + ': ' + R.map(r => String(r.pfad || '').split('/').pop()).join(', ')
      : 'Ablage fehlgeschlagen: ' + String(fehl[0].fehler || (fehl[0].error && fehl[0].error.message) || 'unbekannter Fehler').slice(0, 300);
  }
}
const e = { ok: j.ok === true, fehler: j.ok === true ? '' : String(j.fehler || 'Unbekannter Fehler.'), summen: j.summen || null,
  versand: basis.versand || (j.ok === true && !(j.versand || {}).an ? '' : basis.versand || ''), ablage, versand_ok: basis.versand_ok, ablage_ok, ablage_pfade };
return [{ json: { lauf_id: String(j.lauf_id || ''), e: JSON.stringify(e) } }];

// Antwort (SHOPIFY 2): Ergebnis für den aufrufenden Ablauf. Bei Partner-Abrufen zusätzlich die Datei (PDF bzw. CSV) im Binärfeld „datei“.
const j = $('Bericht erstellen').first();
const J = j.json || {};
const st = (($input.first().json || {}).r || {}).status || (J.ok === true ? 'fertig' : 'fehler');
const aus = { ok: J.ok === true, status: String(st), fehler: J.ok === true ? '' : String(J.fehler || ''), art: String(J.art || '') };
if (J.ok === true && J.art === 'partner') {
  const d = (Array.isArray(J.dateien) ? J.dateien : []).find(x => j.binary && j.binary[x.feld]);
  if (d) {
    // Kopfzeilen für SHOPIFY 4: PDF im Browser anzeigen, CSV herunterladen; Dateiname einfach (ASCII) und vollständig (RFC 5987)
    const einfach = String(d.name).replace(/[^A-Za-z0-9 ._-]/g, '_');
    const disposition = (d.mime === 'text/csv' ? 'attachment' : 'inline') + '; filename="' + einfach + '"; filename*=UTF-8\'\'' + encodeURIComponent(String(d.name));
    return [{ json: Object.assign(aus, { dateiname: d.name, mime: d.mime, typ: d.mime === 'text/csv' ? 'text/csv; charset=utf-8' : 'application/pdf', disposition }), binary: { datei: j.binary[d.feld] } }];
  }
  aus.ok = false; aus.fehler = 'Keine Datei.';
}
return [{ json: aus }];

// Dateien vorbereiten (SHOPIFY 2, Migration 87, Stefan 22.10.2026, 13:03): PDF und CSV eines fertigen Laufs für die Datenbank (shopify_dateien_speichern), damit
// „PDF ansehen“ und „CSV herunterladen“ auf der Berichtsseite gehen (Download nur über ALLY 20 mit Rechteprüfung). Nicht bei Partner-Abrufen. Das Item mit den
// Binärdaten geht unverändert weiter (Token speichern, Mail, Ablage lesen weiter aus „Bericht erstellen“).
const it = $input.first();
const j = it.json || {};
const dateien = [];
if (j.ok === true && j.art !== 'partner' && /^[0-9]{1,18}$/.test(String(j.lauf_id || ''))) {
  for (const d of (Array.isArray(j.dateien) ? j.dateien : [])) {
    if (!['pdf', 'csv'].includes(d.feld) || !it.binary || !it.binary[d.feld]) continue;
    const buf = await this.helpers.getBinaryDataBuffer(0, d.feld);
    if (buf.length > 0 && buf.length <= 26214400) dateien.push({ format: d.feld, name: String(d.name || '').slice(0, 300), b64: buf.toString('base64') });
  }
}
return [{ json: Object.assign({}, j, { dateien_db: JSON.stringify(dateien) }), binary: it.binary }];
